tsOrder=["ExampleBasic","ExampleSize","ExampleWidth","ExampleMaxHeight","ExampleMenuWidth","ExampleMaхMenuHeight","ExampleMenuAlign","ExampleHideMenuIfEmptyInputValue","ExampleType","ExampleDelimiters","ExampleDisabled","ExampleError","ExampleRenderToken","ExampleTotalCount","ExampleOnKeyDown","ExampleCustomItems","ExampleExtendedItems","ExampleFuncDebounceAsync"];ExampleBasic.parameters={...ExampleBasic.parameters,docs:{...ExampleBasic.parameters?.docs,source:{originalSource:"() => {\n  const [selectedItems, setSelectedItems] = React.useState(['Красный', 'Синий']);\n  const delay = time => args => new Promise(resolve => setTimeout(resolve, time, args));\n  const getItems = q => Promise.resolve(['Красный', 'Оранжевый', 'Жёлтый', 'Зелёный', 'Голубой', 'Синий', 'Фиолетовый'].filter(x => x.toLowerCase().includes(q.toLowerCase()) || x.toString() === q)).then(delay(500));\n  return <TokenInput getItems={getItems} selectedItems={selectedItems} onValueChange={setSelectedItems} placeholder=\"Выберите или введите значения\" renderToken={(item, tokenProps) => <Token key={item.toString()} {...tokenProps}>\n          {item}\n        </Token>} />;\n}",...ExampleBasic.parameters?.docs?.source}}},ExampleSize.parameters={...ExampleSize.parameters,docs:{...ExampleSize.parameters?.docs,source:{originalSource:"() => {\n  const [selectedItemsSmall, setSelectedItemsSmall] = React.useState(['Маленький']);\n  const [selectedItemsMedium, setSelectedItemsMedium] = React.useState(['Средний']);\n  const [selectedItemsLarge, setSelectedItemsLarge] = React.useState(['Большой']);\n  const delay = time => args => new Promise(resolve => setTimeout(resolve, time, args));\n  const getItems = q => Promise.resolve(['Маленький', 'Средний', 'Большой'].filter(x => x.toLowerCase().includes(q.toLowerCase()) || x.toString(10) === q)).then(delay(500));\n  return <Gapped vertical>\n      <TokenInput size={'small'} placeholder=\"Введите значение\" getItems={getItems} selectedItems={selectedItemsSmall} onValueChange={setSelectedItemsSmall} />\n      <TokenInput size={'medium'} placeholder=\"Введите значение\" getItems={getItems} selectedItems={selectedItemsMedium} onValueChange={setSelectedItemsMedium} />\n      <TokenInput size={'large'} placeholder=\"Введите значение\" getItems={getItems} selectedItems={selectedItemsLarge} onValueChange={setSelectedItemsLarge} />\n    </Gapped>;\n}",...ExampleSize.parameters?.docs?.source},description:{story:"Проп `size` задаёт размер поля с токенами.",...ExampleSize.parameters?.docs?.description}}},ExampleWidth.parameters={...ExampleWidth.parameters,docs:{...ExampleWidth.parameters?.docs,source:{originalSource:"() => {\n  const [selectedItems, setSelectedItems] = React.useState([]);\n  const delay = time => args => new Promise(resolve => setTimeout(resolve, time, args));\n  const getItems = q => Promise.resolve(['Красный', 'Оранжевый', 'Жёлтый', 'Зелёный', 'Голубой', 'Синий', 'Фиолетовый'].filter(x => x.toLowerCase().includes(q.toLowerCase()) || x.toString(10) === q)).then(delay(500));\n  return <TokenInput width={'350px'} placeholder=\"Введите значения через запятую\" getItems={getItems} selectedItems={selectedItems} onValueChange={setSelectedItems} />;\n}",...ExampleWidth.parameters?.docs?.source},description:{story:"Проп `width` задаёт ширину поля с токенами.",...ExampleWidth.parameters?.docs?.description}}},ExampleMaxHeight.parameters={...ExampleMaxHeight.parameters,docs:{...ExampleMaxHeight.parameters?.docs,source:{originalSource:"() => {\n  const items = Array(30).fill('').map((t, i1) => i1 + Array(5 + i1 % 10).fill('').map((_, i2) => i2).join(''));\n  const [value, setValue] = React.useState<string[]>(items);\n  const getItems = (query: string) => {\n    return Promise.resolve(items.filter(item => item.includes(query)));\n  };\n  return <TokenInput<string> maxHeight={200} width={350} type={TokenInputType.Combined} getItems={getItems} selectedItems={value} onValueChange={setValue} />;\n}",...ExampleMaxHeight.parameters?.docs?.source},description:{story:"Проп `maxHeight` ограничивает высоту поля с токенами. При достижении этой высоты будет появляться скроллбар.",...ExampleMaxHeight.parameters?.docs?.description}}},ExampleMenuWidth.parameters={...ExampleMenuWidth.parameters,docs:{...ExampleMenuWidth.parameters?.docs,source:{originalSource:"() => {\n  const [selectedItems, setSelectedItems] = React.useState([]);\n  const delay = time => args => new Promise(resolve => setTimeout(resolve, time, args));\n  const getItems = q => Promise.resolve(['Красный', 'Оранжевый', 'Жёлтый', 'Зелёный', 'Голубой', 'Синий', 'Фиолетовый'].filter(x => x.toLowerCase().includes(q.toLowerCase()) || x.toString(10) === q)).then(delay(500));\n  return <Gapped vertical>\n      <TokenInput placeholder=\"Введите значение\" menuWidth=\"auto\" getItems={getItems} selectedItems={selectedItems} onValueChange={setSelectedItems} />\n      <TokenInput placeholder=\"Введите значение\" menuAlign=\"left\" menuWidth={'200px'} getItems={getItems} selectedItems={selectedItems} onValueChange={setSelectedItems} />\n      <TokenInput placeholder=\"Введите значение\" menuAlign=\"left\" menuWidth={'120%'} getItems={getItems} selectedItems={selectedItems} onValueChange={setSelectedItems} />\n    </Gapped>;\n}",...ExampleMenuWidth.parameters?.docs?.source},description:{story:"Проп `menuWidth` задаёт максимальную ширину выпадающего списка. Может быть `auto` — по ширине текста, в пикселях, процентах от ширины поля и других конкретных единицах.\n\nПроп зависит от другого пропа `menuAlign`. Ширина выпадающего списка всегда будет равна `\"auto\"`, когда  'menuAlign'='cursor' — для поля с токенами является значением по умолчанию.",...ExampleMenuWidth.parameters?.docs?.description}}},ExampleMaхMenuHeight.parameters={...ExampleMaхMenuHeight.parameters,docs:{...ExampleMaхMenuHeight.parameters?.docs,source:{originalSource:"() => {\n  const [selectedItems, setSelectedItems] = React.useState([]);\n  const delay = time => args => new Promise(resolve => setTimeout(resolve, time, args));\n  const getItems = q => Promise.resolve(['Красный', 'Оранжевый', 'Жёлтый', 'Зелёный', 'Голубой', 'Синий', 'Фиолетовый'].filter(x => x.toLowerCase().includes(q.toLowerCase()) || x.toString(10) === q)).then(delay(500));\n  return <TokenInput placeholder=\"Введите значение\" maxMenuHeight={'100px'} getItems={getItems} selectedItems={selectedItems} onValueChange={setSelectedItems} />;\n}",...ExampleMaхMenuHeight.parameters?.docs?.source},description:{story:"Проп `maxMenuHeight` задаёт максимальную высоту выпадающего списка.",...ExampleMaхMenuHeight.parameters?.docs?.description}}},ExampleMenuAlign.parameters={...ExampleMenuAlign.parameters,docs:{...ExampleMenuAlign.parameters?.docs,source:{originalSource:"() => {\n  const [selectedItems, setSelectedItems] = React.useState(['Красный']);\n  const [selectedItemsLeft, setSelectedItemsLeft] = React.useState(['Красный']);\n  const delay = time => args => new Promise(resolve => setTimeout(resolve, time, args));\n  const getItems = q => Promise.resolve(['Красный', 'Оранжевый', 'Жёлтый', 'Зелёный', 'Голубой', 'Синий', 'Фиолетовый'].filter(x => x.toLowerCase().includes(q.toLowerCase()) || x.toString(10) === q)).then(delay(500));\n  return <Gapped vertical>\n      <Gapped>\n        <TokenInput placeholder=\"Введите значение\" menuAlign=\"cursor\" getItems={getItems} selectedItems={selectedItems} onValueChange={setSelectedItems} />\n        <span>menuAlign=\"cursor\"</span>\n      </Gapped>\n      <Gapped>\n        <TokenInput placeholder=\"Введите значение\" menuAlign=\"left\" getItems={getItems} selectedItems={selectedItemsLeft} onValueChange={setSelectedItemsLeft} />\n        <span>menuAlign=\"left\"</span>\n      </Gapped>\n    </Gapped>;\n}",...ExampleMenuAlign.parameters?.docs?.source},description:{story:'Проп `menuAlign` выравнивает выпадающий список. По умолчанию `cursor` — выпадающий список отображается по линии текущего положения курсора в поле с токенами. Можно закрепить строго по левому краю через значение `"left"`.',...ExampleMenuAlign.parameters?.docs?.description}}},ExampleHideMenuIfEmptyInputValue.parameters={...ExampleHideMenuIfEmptyInputValue.parameters,docs:{...ExampleHideMenuIfEmptyInputValue.parameters?.docs,source:{originalSource:"() => {\n  const [selectedItems, setSelectedItems] = React.useState([]);\n  const delay = time => args => new Promise(resolve => setTimeout(resolve, time, args));\n  const getItems = q => Promise.resolve(['Красный', 'Оранжевый', 'Жёлтый', 'Зелёный', 'Голубой', 'Синий', 'Фиолетовый'].filter(x => x.toLowerCase().includes(q.toLowerCase()) || x.toString(10) === q)).then(delay(500));\n  return <Gapped vertical>\n      <Gapped>\n        <TokenInput placeholder=\"Введите значение\" getItems={getItems} selectedItems={selectedItems} onValueChange={setSelectedItems} />\n        <span>Обычное поле</span>\n      </Gapped>\n      <Gapped>\n        <TokenInput placeholder=\"Введите значение\" hideMenuIfEmptyInputValue getItems={getItems} selectedItems={selectedItems} onValueChange={setSelectedItems} />\n        <span>С пропом \"hideMenuIfEmptyInputValue\"</span>\n      </Gapped>\n    </Gapped>;\n}",...ExampleHideMenuIfEmptyInputValue.parameters?.docs?.source},description:{story:"По умолчанию выпадающий список с подсказками появляется сразу при фокусе в поле и продолжает отображаться всё время, пока пользователь вводит в поле токены.\n\nПроп `hideMenuIfEmptyInputValue` отключает это поведение. Такой режим похож на работу [автокомплита](https://tech.skbkontur.ru/kontur-ui/?path=/docs/react-ui_input-data-autocomplete--docs). Выпадающий список появляется, когда введён первый символ первого или последующего токена.",...ExampleHideMenuIfEmptyInputValue.parameters?.docs?.description}}},ExampleType.parameters={...ExampleType.parameters,docs:{...ExampleType.parameters?.docs,source:{originalSource:"() => {\n  const [selectedItemsCombined, setSelectedItemsCombined] = React.useState([]);\n  const [selectedItemsWithReference, setSelectedItemsWithReference] = React.useState([]);\n  const [selectedItemsWithoutReference, setSelectedItemsWithoutReference] = React.useState([]);\n  const delay = time => args => new Promise(resolve => setTimeout(resolve, time, args));\n  const getItems = q => Promise.resolve(['Маленький', 'Средний', 'Большой'].filter(x => x.toLowerCase().includes(q.toLowerCase()) || x.toString(10) === q)).then(delay(500));\n  return <Gapped vertical>\n      <Gapped>\n        <TokenInput placeholder=\"Введите значение\" type={TokenInputType.Combined} getItems={getItems} selectedItems={selectedItemsCombined} onValueChange={setSelectedItemsCombined} />\n        <span>TokenInputType.Combined</span>\n      </Gapped>\n      <Gapped>\n        <TokenInput placeholder=\"Введите значение\" type={TokenInputType.WithReference} getItems={getItems} selectedItems={selectedItemsWithReference} onValueChange={setSelectedItemsWithReference} />\n        <span>TokenInputType.WithReference</span>\n      </Gapped>\n      <Gapped>\n        <TokenInput placeholder=\"Введите значение через запятую\" type={TokenInputType.WithoutReference} getItems={getItems} selectedItems={selectedItemsWithoutReference} onValueChange={setSelectedItemsWithoutReference} />\n        <span>TokenInputType.WithoutReference</span>\n      </Gapped>\n    </Gapped>;\n}",...ExampleType.parameters?.docs?.source},description:{story:"Проп `type` задаёт тип поля:\n- `TokenInputType.Combined` — можно и выбирать, и добавлять значения.\n- `TokenInputType.WithReference` — в поле можно ввести только значения из справочника, но нельзя добавлять свои.\n- `TokenInputType.WithoutReference` — можно добавлять любые значения, но подсказок из справочника нет.",...ExampleType.parameters?.docs?.description}}},ExampleDelimiters.parameters={...ExampleDelimiters.parameters,docs:{...ExampleDelimiters.parameters?.docs,source:{originalSource:"() => {\n  const [selectedItems, setSelectedItems] = React.useState(['Красный', 'Синий']);\n  const delay = time => args => new Promise(resolve => setTimeout(resolve, time, args));\n  const getItems = q => Promise.resolve(['Красный', 'Оранжевый', 'Жёлтый', 'Зелёный', 'Голубой', 'Синий', 'Фиолетовый'].filter(x => x.toLowerCase().includes(q.toLowerCase()) || x.toString() === q)).then(delay(500));\n  const customLocale = {\n    TokenInput: {\n      addButtonComment: 'Нажмите точку'\n    }\n  };\n  return <LocaleContext.Provider value={{\n    locale: customLocale\n  }}>\n      <TokenInput getItems={getItems} selectedItems={selectedItems} onValueChange={setSelectedItems} type={TokenInputType.Combined} placeholder=\"Выберите или введите значения\" delimiters={['.']} renderToken={(item, tokenProps) => <Token key={item.toString()} {...tokenProps}>\n            {item}\n          </Token>} />\n    </LocaleContext.Provider>;\n}",...ExampleDelimiters.parameters?.docs?.source},description:{story:"Проп `delimiters` определяет знак разделителя токенов при вводе. По умолчанию запятая.\n\nРаботает только с типами `TokenInputType.WithoutReference` и `TokenInputType.Combined`.\n\nПри смене разделителей смените текст для подсказки добавления нового токена, по умолчанию — «Нажмите запятую».",...ExampleDelimiters.parameters?.docs?.description}}},ExampleDisabled.parameters={...ExampleDisabled.parameters,docs:{...ExampleDisabled.parameters?.docs,source:{originalSource:"() => {\n  const [selectedItems, setSelectedItems] = React.useState(['Красный', 'Синий']);\n  const delay = time => args => new Promise(resolve => setTimeout(resolve, time, args));\n  const getItems = q => Promise.resolve(['Красный', 'Оранжевый', 'Жёлтый', 'Зелёный', 'Голубой', 'Синий', 'Фиолетовый'].filter(x => x.toLowerCase().includes(q.toLowerCase()) || x.toString() === q)).then(delay(500));\n  return <TokenInput getItems={getItems} selectedItems={selectedItems} onValueChange={setSelectedItems} placeholder=\"Выберите или введите значения\" disabled renderToken={(item, tokenProps) => <Token key={item.toString()} {...tokenProps}>\n          {item}\n        </Token>} />;\n}",...ExampleDisabled.parameters?.docs?.source},description:{story:"Проп `disabled` блокирует поле с токенами. Поле меняет цвет на серый и становится недоступно для редактирования.",...ExampleDisabled.parameters?.docs?.description}}},ExampleError.parameters={...ExampleError.parameters,docs:{...ExampleError.parameters?.docs,source:{originalSource:"() => {\n  const [selectedItems, setSelectedItems] = React.useState(['Красный', 'Синий']);\n  const delay = time => args => new Promise(resolve => setTimeout(resolve, time, args));\n  const getItems = q => Promise.resolve(['Красный', 'Оранжевый', 'Жёлтый', 'Зелёный', 'Голубой', 'Синий', 'Фиолетовый'].filter(x => x.toLowerCase().includes(q.toLowerCase()) || x.toString() === q)).then(delay(500));\n  return <TokenInput getItems={getItems} selectedItems={selectedItems} onValueChange={setSelectedItems} placeholder=\"Выберите или введите значения\" error renderToken={(item, tokenProps) => <Token key={item.toString()} {...tokenProps}>\n          {item}\n        </Token>} />;\n}",...ExampleError.parameters?.docs?.source},description:{story:"Проп `error` переводит поле с токенами в состояние ошибки. Поле подсвечивается красной рамкой.",...ExampleError.parameters?.docs?.description}}},ExampleRenderToken.parameters={...ExampleRenderToken.parameters,docs:{...ExampleRenderToken.parameters?.docs,source:{originalSource:"() => {\n  const [selectedItems, setSelectedItems] = React.useState(['Красный', 'Синий', 'Зелёный']);\n  async function getItems(query) {\n    return ['Красный', 'Синий', 'Зелёный'].filter(s => s.includes(query));\n  }\n  return <TokenInput type={TokenInputType.Combined} getItems={getItems} selectedItems={selectedItems} onValueChange={setSelectedItems} renderToken={(item, tokenProps) => <Token key={item.toString()} {...tokenProps} disabled={item === 'Синий' || tokenProps.disabled}>\n          {item}\n        </Token>} />;\n}",...ExampleRenderToken.parameters?.docs?.source},description:{story:"Проп `renderToken` задаёт функцию, которая отображает токен и даёт возможность кастомизировать внешний вид и поведение токена.",...ExampleRenderToken.parameters?.docs?.description}}},ExampleTotalCount.parameters={...ExampleTotalCount.parameters,docs:{...ExampleTotalCount.parameters?.docs,source:{originalSource:"() => {\n  const delay = time => args => new Promise(resolve => setTimeout(resolve, time, args));\n  const maxItems = 5;\n  const [totalCount, setTotalCount] = React.useState(cities.length);\n  const [value, setValue] = React.useState([]);\n  const getItems = query => {\n    const items = cities.map(x => x.City).filter(x => x.toLowerCase().includes(query.toLowerCase()) || x.toString() === query);\n    const result = items.slice(0, maxItems);\n    setTotalCount(items.length);\n    return Promise.resolve(result).then(delay(500));\n  };\n  const renderTotalCount = (foundCount, totalCount) => <span>\n      Показано {foundCount} из {totalCount} найденных городов\n    </span>;\n  return <div style={{\n    width: '300px'\n  }}>\n      <TokenInput type={TokenInputType.Combined} selectedItems={value} onValueChange={setValue} getItems={getItems} placeholder=\"Выберите или введите значение\" renderTotalCount={renderTotalCount} totalCount={totalCount} />\n    </div>;\n}",...ExampleTotalCount.parameters?.docs?.source},description:{story:"Пропсы `totalCount` и `renderTotalCount` позволяют добавить в выпадающий список счётчик найденных значений.\n- `renderTotalCount` — задаёт функцию, которая отображает сообщение о количестве значений.\n- `totalCount` — определяет общее количество значений.\n\nВ примере также настроено ограничение количества значений в результате поиска.",...ExampleTotalCount.parameters?.docs?.description}}},ExampleOnKeyDown.parameters={...ExampleOnKeyDown.parameters,docs:{...ExampleOnKeyDown.parameters?.docs,source:{originalSource:"() => {\n  const [value, setValue] = React.useState<string[]>([]);\n  const tokenInputRef = React.useRef<TokenInput>(null);\n  const items = ['Красный', 'Оранжевый', 'Жёлтый', 'Зелёный', 'Голубой', 'Синий', 'Фиолетовый'];\n  const getItems = (query: string) => {\n    return Promise.resolve(items.filter(item => item.includes(query)));\n  };\n  return <TokenInput<string> ref={tokenInputRef} selectedItems={value} onValueChange={setValue} getItems={getItems} placeholder=\"Запрещён символ @\" onKeyDown={e => {\n    if (e.key === '@') {\n      e.preventDefault();\n      tokenInputRef.current?.blink();\n    }\n  }} />;\n}",...ExampleOnKeyDown.parameters?.docs?.source},description:{story:"Проп `onKeyDown` вызывает HTML-событие `onkeydown`. Вызывая `preventDefault` на его события можно нативно блокировать ввод конкретных символов.",...ExampleOnKeyDown.parameters?.docs?.description}}},ExampleCustomItems.parameters={...ExampleCustomItems.parameters,docs:{...ExampleCustomItems.parameters?.docs,source:{originalSource:"() => {\n  const [selectedItems, setSelectedItems] = React.useState([]);\n  const delay = time => args => new Promise(resolve => setTimeout(resolve, time, args));\n  const getGenericItems = () => [{\n    id: '1',\n    value: 'Красный'\n  }, {\n    id: '2',\n    value: 'Оранжевый'\n  }, {\n    id: '3',\n    value: 'Жёлтый'\n  }, {\n    id: '4',\n    value: 'Зелёный'\n  }];\n  const renderItem = item => item.value;\n  const renderValue = value => value.value;\n  const valueToItem = item => ({\n    value: item\n  });\n  const getModelItems = async query => {\n    await delay(400);\n    return getGenericItems().filter(s => s.value.includes(query));\n  };\n  return <div style={{\n    width: '300px'\n  }}>\n      <TokenInput selectedItems={selectedItems} renderItem={renderItem} renderValue={renderValue} valueToItem={valueToItem} valueToString={renderValue} getItems={getModelItems} onValueChange={setSelectedItems} placeholder=\"Выберите или введите значение\" type={TokenInputType.Combined} renderToken={(item, tokenProps) => <Token key={item.id} {...tokenProps}>\n            {item.value}\n          </Token>} />\n    </div>;\n}",...ExampleCustomItems.parameters?.docs?.source},description:{story:"В примере показано, как передать кастомный тип значений для справочника.",...ExampleCustomItems.parameters?.docs?.description}}},ExampleExtendedItems.parameters={...ExampleExtendedItems.parameters,docs:{...ExampleExtendedItems.parameters?.docs,source:{originalSource:"() => {\n  const [selectedItems, setSelectedItems] = React.useState<string[]>();\n  return <TokenInput selectedItems={selectedItems} onValueChange={setSelectedItems} getItems={async (q: string) => [<MenuHeader>MenuHeader</MenuHeader>, 'Красный', 'Синий', <MenuSeparator />, 'Жёлтый', 'Зелёный', <MenuFooter>MenuFooter</MenuFooter>].filter(i => typeof i === 'string' ? i.toLowerCase().includes(q.toLowerCase()) : q === '')} />;\n}",...ExampleExtendedItems.parameters?.docs?.source},description:{story:"В массиве, возвращаемом `getItems`, могут быть переданы React-компоненты:\n`<MenuHeader>`, `<MenuFooter>`, `<MenuSeparator />` и любые другие.\n\nВ таких случаях поиск необходимо контролировать дополнительно.",...ExampleExtendedItems.parameters?.docs?.description}}},ExampleFuncDebounceAsync.parameters={...ExampleFuncDebounceAsync.parameters,docs:{...ExampleFuncDebounceAsync.parameters?.docs,source:{originalSource:"() => {\n  const [value, setValue] = React.useState([]);\n  function debounceAsync(callback, wait) {\n    let timeoutId = null;\n    return (...args) => {\n      if (timeoutId) {\n        clearTimeout(timeoutId);\n      }\n      return new Promise(resolve => {\n        const timeoutPromise = new Promise(resolve => {\n          timeoutId = setTimeout(resolve, wait);\n        });\n        timeoutPromise.then(async () => {\n          resolve(await callback(...args));\n        });\n      });\n    };\n  }\n  const items = ['Красный', 'Оранжевый', 'Жёлтый', 'Зелёный', 'Голубой', 'Синий', 'Фиолетовый'];\n  const getItems = async query => {\n    console.log('query: ', query);\n    return items.filter(item => item.includes(query));\n  };\n  return <TokenInput style={{\n    width: '300px'\n  }} type={TokenInputType.Combined} selectedItems={value} onValueChange={setValue} getItems={debounceAsync(getItems, 300)} placeholder=\"Выберите или введите значение\" />;\n}",...ExampleFuncDebounceAsync.parameters?.docs?.source},description:{story:"Функция `debounce` из lodash некорректно работает с `async/promise`, поэтому лучше использовать кастомную функцию, как в примере ниже.",...ExampleFuncDebounceAsync.parameters?.docs?.description}}};try{ExampleSize.displayName="ExampleSize",ExampleSize.__docgenInfo={description:"Проп `size` задаёт размер поля с токенами.",displayName:"ExampleSize",props:{}},"undefined"!=typeof STORYBOOK_REACT_CLASSES&&(STORYBOOK_REACT_CLASSES["components/TokenInput/__docs__/TokenInput.docs.stories.tsx#ExampleSize"]={docgenInfo:ExampleSize.__docgenInfo,name:"ExampleSize",path:"components/TokenInput/__docs__/TokenInput.docs.stories.tsx#ExampleSize"})}catch(__react_docgen_typescript_loader_error){}try{ExampleWidth.displayName="ExampleWidth",ExampleWidth.__docgenInfo={description:"Проп `width` задаёт ширину поля с токенами.",displayName:"ExampleWidth",props:{}},"undefined"!=typeof STORYBOOK_REACT_CLASSES&&(STORYBOOK_REACT_CLASSES["components/TokenInput/__docs__/TokenInput.docs.stories.tsx#ExampleWidth"]={docgenInfo:ExampleWidth.__docgenInfo,name:"ExampleWidth",path:"components/TokenInput/__docs__/TokenInput.docs.stories.tsx#ExampleWidth"})}catch(__react_docgen_typescript_loader_error){}try{ExampleMaxHeight.displayName="ExampleMaxHeight",ExampleMaxHeight.__docgenInfo={description:"Проп `maxHeight` ограничивает высоту поля с токенами. При достижении этой высоты будет появляться скроллбар.",displayName:"ExampleMaxHeight",props:{}},"undefined"!=typeof STORYBOOK_REACT_CLASSES&&(STORYBOOK_REACT_CLASSES["components/TokenInput/__docs__/TokenInput.docs.stories.tsx#ExampleMaxHeight"]={docgenInfo:ExampleMaxHeight.__docgenInfo,name:"ExampleMaxHeight",path:"components/TokenInput/__docs__/TokenInput.docs.stories.tsx#ExampleMaxHeight"})}catch(__react_docgen_typescript_loader_error){}try{ExampleMenuWidth.displayName="ExampleMenuWidth",ExampleMenuWidth.__docgenInfo={description:"Проп `menuWidth` задаёт максимальную ширину выпадающего списка. Может быть `auto` — по ширине текста, в пикселях, процентах от ширины поля и других конкретных единицах.\n\nПроп зависит от другого пропа `menuAlign`. Ширина выпадающего списка всегда будет равна `\"auto\"`, когда  'menuAlign'='cursor' — для поля с токенами является значением по умолчанию.",displayName:"ExampleMenuWidth",props:{}},"undefined"!=typeof STORYBOOK_REACT_CLASSES&&(STORYBOOK_REACT_CLASSES["components/TokenInput/__docs__/TokenInput.docs.stories.tsx#ExampleMenuWidth"]={docgenInfo:ExampleMenuWidth.__docgenInfo,name:"ExampleMenuWidth",path:"components/TokenInput/__docs__/TokenInput.docs.stories.tsx#ExampleMenuWidth"})}catch(__react_docgen_typescript_loader_error){}try{ExampleMaхMenuHeight.displayName="ExampleMaхMenuHeight",ExampleMaхMenuHeight.__docgenInfo={description:"Проп `maxMenuHeight` задаёт максимальную высоту выпадающего списка.",displayName:"ExampleMaхMenuHeight",props:{}},"undefined"!=typeof STORYBOOK_REACT_CLASSES&&(STORYBOOK_REACT_CLASSES["components/TokenInput/__docs__/TokenInput.docs.stories.tsx#ExampleMaхMenuHeight"]={docgenInfo:ExampleMaхMenuHeight.__docgenInfo,name:"ExampleMaхMenuHeight",path:"components/TokenInput/__docs__/TokenInput.docs.stories.tsx#ExampleMaхMenuHeight"})}catch(__react_docgen_typescript_loader_error){}try{ExampleMenuAlign.displayName="ExampleMenuAlign",ExampleMenuAlign.__docgenInfo={description:'Проп `menuAlign` выравнивает выпадающий список. По умолчанию `cursor` — выпадающий список отображается по линии текущего положения курсора в поле с токенами. Можно закрепить строго по левому краю через значение `"left"`.',displayName:"ExampleMenuAlign",props:{}},"undefined"!=typeof STORYBOOK_REACT_CLASSES&&(STORYBOOK_REACT_CLASSES["components/TokenInput/__docs__/TokenInput.docs.stories.tsx#ExampleMenuAlign"]={docgenInfo:ExampleMenuAlign.__docgenInfo,name:"ExampleMenuAlign",path:"components/TokenInput/__docs__/TokenInput.docs.stories.tsx#ExampleMenuAlign"})}catch(__react_docgen_typescript_loader_error){}try{ExampleHideMenuIfEmptyInputValue.displayName="ExampleHideMenuIfEmptyInputValue",ExampleHideMenuIfEmptyInputValue.__docgenInfo={description:"По умолчанию выпадающий список с подсказками появляется сразу при фокусе в поле и продолжает отображаться всё время, пока пользователь вводит в поле токены.\n\nПроп `hideMenuIfEmptyInputValue` отключает это поведение. Такой режим похож на работу [автокомплита](https://tech.skbkontur.ru/kontur-ui/?path=/docs/react-ui_input-data-autocomplete--docs). Выпадающий список появляется, когда введён первый символ первого или последующего токена.",displayName:"ExampleHideMenuIfEmptyInputValue",props:{}},"undefined"!=typeof STORYBOOK_REACT_CLASSES&&(STORYBOOK_REACT_CLASSES["components/TokenInput/__docs__/TokenInput.docs.stories.tsx#ExampleHideMenuIfEmptyInputValue"]={docgenInfo:ExampleHideMenuIfEmptyInputValue.__docgenInfo,name:"ExampleHideMenuIfEmptyInputValue",path:"components/TokenInput/__docs__/TokenInput.docs.stories.tsx#ExampleHideMenuIfEmptyInputValue"})}catch(__react_docgen_typescript_loader_error){}try{ExampleType.displayName="ExampleType",ExampleType.__docgenInfo={description:"Проп `type` задаёт тип поля:\n- `TokenInputType.Combined` — можно и выбирать, и добавлять значения.\n- `TokenInputType.WithReference` — в поле можно ввести только значения из справочника, но нельзя добавлять свои.\n- `TokenInputType.WithoutReference` — можно добавлять любые значения, но подсказок из справочника нет.",displayName:"ExampleType",props:{}},"undefined"!=typeof STORYBOOK_REACT_CLASSES&&(STORYBOOK_REACT_CLASSES["components/TokenInput/__docs__/TokenInput.docs.stories.tsx#ExampleType"]={docgenInfo:ExampleType.__docgenInfo,name:"ExampleType",path:"components/TokenInput/__docs__/TokenInput.docs.stories.tsx#ExampleType"})}